def start(l,c):
    if l=='zh':
        lead='从源码开始，先了解边界。'; desc='迹库目前面向愿意自行构建、检查与参与的使用者。没有应用商店下载，也没有即装即用的完整自动记忆服务。'
        blocks=[('01','准备构建环境','原生客户端需要 Mac、Xcode 26 或以上及手机与手表平台组件。最低部署目标为 macOS 14、iOS 18、watchOS 11；不代表每个系统版本均已实测。当前桌面内置节点依赖系统 Python 3。'),('02','按公开指南构建','阅读仓库开发说明后，克隆源码、准备节点运行时并生成工程。桌面与模拟器可以无个人签名构建；真机运行需要自己的签名设置。不要提交个人签名或设备信息。'),('03','用合成资料先试一遍','先使用少量非敏感测试文字，预览后确认导入，再检查检索结果、来源版本和导出。不要一开始就把唯一的真实资料交给开发版。'),('04','按需配置服务','导入不会自动发送给模型。模型处理取决于你选择的提供商、配置与启用，自备服务可能收费。语音转写需独立配置并主动发送，或另行开启新录音自动转写。适配器与持久队列已实现，真实服务质量未验收。')]
        limits='开始前，请知道'; items=['目前没有已签名、公证的安装包，普通用户安装体验仍在完善。','客户端可选择片段、预览后发送模型回答，也可明确发起模型记忆建议与批量整理，仍由本人确认。CLI 保持授权只读检索。','真实模型质量、异地云同步和后台链路尚未完成验收。','便携文字导出不是恢复包。另有未加密的独立备份与恢复；跨机器与干净系统恢复仍待验收。']; guide='打开完整构建指南'; more='开发说明是客户端构建的维护入口。此静态官网不运行资料节点，也不接收你的文件。'
    else:
        lead='Start with source. Know the boundaries.'; desc='Tracebook is currently for people willing to build, inspect and contribute. There is no App Store download or ready-to-install complete automatic memory service.'
        blocks=[('01','Prepare your build environment','Native clients require a Mac, Xcode 26 or later, and iPhone and watch platform components. Minimum targets are macOS 14, iOS 18 and watchOS 11, not a claim of testing on every version. The desktop node currently depends on system Python 3.'),('02','Follow the public build guide','Read the development guide, clone the source, prepare the node runtime and generate the project. Desktop and simulator builds can omit personal signing; physical devices require your own signing configuration. Never commit signing or device information.'),('03','Try synthetic material first','Start with a small amount of non-sensitive test text. Preview and confirm the import, then check search results, source versions and export. Do not entrust your only copy of real material to a development release.'),('04','Configure services deliberately','Import does not automatically send material to a model. Processing depends on the provider you choose, your configuration and activation. Your provider may charge fees. Speech transcription needs separate configuration and explicit sending, or opt-in automatic processing of newly received audio. The adapter and durable queue are implemented; real-service quality is not validated.')]
        limits='Before you begin'; items=['No signed, notarized installer is available. Everyday installation is still being developed.','Clients can select and preview passages for model answers, or explicitly request model memory candidates and batch organization, still requiring human confirmation. The CLI remains scoped read-only retrieval.','Real-model quality, remote cloud sync and background workflows are not fully validated.','Portable text export is not a restore package. Separate unencrypted backup and restoration exist; cross-machine and clean-system restoration still need validation.']; guide='Open the full build guide'; more='The development guide is the maintained source for client build instructions. This static website does not run a data node or receive your files.'
    return f'<div class="page-intro"><p class="eyebrow">GET STARTED</p><h1>{lead}</h1><p class="intro">{desc}</p></div><div class="reading">'+''.join(f'<section class="guide-step"><span class="number">{n}</span><div><h2>{h}</h2><p>{b}</p></div></section>' for n,h,b in blocks)+f'<div class="guide-cta">{link("/blob/main/docs/development.md",guide,"button primary")}<p class="small">{more}</p></div><section class="notice"><h2>{limits}</h2><ul>'+''.join(f'<li>{i}</li>' for i in items)+f'</ul>{link("/blob/main/ROADMAP.md",c["roadmap"],"text-link")}</section></div>'
def privacy(l,c):
    if l=='zh':
        lead='资料归你，边界说清楚。'; desc='本地优先不意味着数据绝不会离开设备。了解网站、客户端、模型服务和外部读取分别做什么，再决定如何使用。'
        blocks=[('这个网站','本站是静态介绍页，不自建账号，不加入统计脚本、收集表单、广告或追踪 Cookie。页面不上传个人资料。访问外部源码和文档链接时，目标网站按其自己的规则处理请求；本站托管在 ChatGPT Sites，当前为公开访问；托管平台可能记录常规访问日志。'),('导入与原始来源','来源目录只读，先预览再确认。登录文件与完整配置不归档，但常见凭证过滤不能识别全部私人信息。导入不会自动发送给模型，也不会自动把他人发言或助手回答变成你的事实。'),('模型与费用','第三方模型处理取决于用户的配置与启用。启用处理前，应核对服务商、发送内容、保留政策与费用。语音转写默认不自动外发；逐条启动或明确开启自动处理会把原音发送到已配置的语音服务。语音和文字模型是不同角色；自备模型服务可能计费，项目不承诺免费模型服务。'),('文件、同步与备份','资料放在用户选择的文件夹。文字导出排除凭证与原音，不是完整备份恢复。另有独立备份，包含已接收原音、归档文字、记忆、来源与历史；备份未加密，排除凭证、外部原件与未确认导入。恢复建立独立副本并暂停自动任务，跨机器与干净系统恢复仍待验收。使用同步资料夹时，相关资料会受你所选同步服务的规则约束。真实异地与后台同步链路仍待验收，不能把同步等同于备份。'),('外部读取与网络','节点默认只监听本机。外部只读凭证有独立范围、期限与撤销，新资料类型需要单独授权。局域网直连需明确启用；普通 HTTP 不加密，不应把节点直接暴露到公网。远程访问需要有效 HTTPS。'),('安全问题与开发状态','这是早期开发版本，不承诺生产环境安全认证。报告问题时只使用最小复现和合成数据，不公开真实录音、聊天、模型密钥、数据库或完整日志。')]; security='阅读完整安全说明'; report='私密报告安全问题'; date='本说明依据当前公开实现，不替代你所选服务商的隐私政策。'
    else:
        lead='Your material. Clear boundaries.'; desc='Local-first does not mean data can never leave a device. Understand the website, clients, model services and external access before choosing how to use them.'
        blocks=[('This website','This is a static information site, with no self-built account system, analytics scripts, collection forms, ads or tracking cookies. It does not upload personal material. External source and documentation links are handled under the destination’s own policies. This website is hosted on ChatGPT Sites and is currently publicly accessible. The hosting platform may keep ordinary access logs.'),('Imports and original sources','Source directories are read-only, with preview before confirmation. Login files and full configurations are not archived, but common credential filtering cannot detect all private information. Imports do not automatically go to a model or turn other people’s statements and assistant replies into facts about you.'),('Models and fees','Third-party model processing depends on your configuration and activation. Before enabling it, check the provider, content sent, retention policies and fees. Speech transcription does not automatically send audio by default. Starting a task or opting into automatic processing sends original audio to your configured speech provider. Speech and text models have separate roles. Your chosen model provider may charge fees; the project does not promise free model services.'),('Files, sync and backup','Material lives in a folder you choose. Text export excludes credentials and original audio and is not a full backup or restore format. Separate backups include received audio, archived text, memories, sources and history. They are unencrypted and exclude credentials, external originals and unconfirmed imports. Restoration creates an independent copy with automatic tasks paused; cross-machine and clean-system restoration still need validation. A sync folder is subject to your chosen sync provider’s policies. Real remote and background sync workflows still need validation. Sync is not backup.'),('External access and networking','The node listens locally by default. External read-only credentials have separate scopes, expiry and revocation; new material types need their own authorization. LAN access must be explicitly enabled. Plain HTTP is unencrypted; do not expose the node directly to the public internet. Remote access requires valid HTTPS.'),('Security and development status','This is an early development release, without a claim of production security certification. Report issues with a minimal reproduction and synthetic data. Do not publicly share real recordings, chats, model keys, databases or full logs.')]; security='Read the full security guidance'; report='Report a vulnerability privately'; date='This explanation reflects the public implementation, not a replacement for your chosen providers’ privacy policies.'
    return f'<div class="page-intro"><p class="eyebrow">PRIVACY & OWNERSHIP</p><h1>{lead}</h1><p class="intro">{desc}</p></div><div class="reading privacy-copy">'+''.join(f'<section><h2>{h}</h2><p>{b}</p></section>' for h,b in blocks)+f'<div class="actions">{link("/blob/main/SECURITY.md",security,"text-link")}{link("/security/advisories/new",report,"text-link")}</div><p class="small">{date}</p></div>'
def render(l,page):
    if page=='home':return precision_home(l)
    c=COPY[l];prefix='../' if l=='en' else '';file='start.html' if page=='start' else 'privacy.html';other='../'+file if l=='en' else 'en/'+file
    body={'start':start,'privacy':privacy}[page](l,c)
    return f'''<!doctype html><html lang="{c['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{c['name']} · {c[page]}"><title>{c[page]} · {c['name']}</title><link rel="icon" href="{prefix}assets/favicon.png"><link rel="stylesheet" href="{prefix}assets/tokens.css"><link rel="stylesheet" href="{prefix}assets/slice.css"><link rel="stylesheet" href="{prefix}assets/whole.css"></head><body><a class="skip" href="#main">{c['skip']}</a><header class="site-nav"><a class="brand" href="index.html"><img src="{prefix}assets/brand-mark.png" alt="" width="28" height="28">{c['name']}</a><nav aria-label="{c['nav']}"><a href="index.html">{c['home']}</a><a href="start.html">{c['start']}</a><a href="{other}">{c['switch']}</a></nav></header><main id="main" class="article-page" tabindex="-1">{body}</main>{precision_footer(l)}</body></html>'''
def build():
    # Only explicit public website assets enter the deployable output.
    if OUT.exists():shutil.rmtree(OUT)
    (OUT/'assets').mkdir(parents=True)
    for name in ['tokens.css','slice.css','whole.css','motion.js','whole.js']:
        shutil.copy2(ROOT/'precision'/name,OUT/'assets'/name)
    for name in ['brand-mark.png','favicon.png','precision-tap-v1.png']:
        shutil.copy2(ROOT/'assets'/name,OUT/'assets'/name)
    for l in COPY:
        folder=OUT/('en' if l=='en' else '')
        folder.mkdir(exist_ok=True)
        for page,file in [('home','index.html'),('start','start.html'),('privacy','privacy.html')]:
            (folder/file).write_text(render(l,page),encoding='utf-8')
    print('Built 6 static pages with explicit public assets in website/dist.')
if __name__=='__main__':build()
